  it('adds Easy Apply from the extension metadata when the sanitized snapshot has no UI signal', async () => { const app = make(); const response = await app.inject({ method: 'POST', url: '/api/snapshots/import', headers: { authorization: 'Bearer token' }, payload: { ...snapshot, metadata: { collector_version: '1.3.0', easy_apply: true }, snapshot: { format: 'html', text: null, html: '<section data-snapshot-section="description"><p>Develop polymer materials.</p></section>' } } }); const job = await app.inject({ method: 'GET', url: `/api/jobs/${response.json().job_id}` }); expect(job.json().tags).toEqual(expect.arrayContaining([expect.objectContaining({ name: 'Easy Apply' })])); });
  it('does not infer Easy Apply from the LinkedIn job description alone', async () => { const app = make(); const response = await app.inject({ method: 'POST', url: '/api/snapshots/import', headers: { authorization: 'Bearer token' }, payload: { ...snapshot, source: 'linkedin', url: 'https://www.linkedin.com/jobs/view/999999', snapshot: { format: 'html', text: null, html: '<section data-snapshot-section="header"><h1>Materials Engineer</h1><p>Berlin, Germany</p></section><section data-snapshot-section="description"><p>Use our Easy Apply workflow after reviewing the role.</p></section>' } } }); const job = await app.inject({ method: 'GET', url: `/api/jobs/${response.json().job_id}`, headers: { authorization: 'Bearer token' } }); expect(job.json().tags).toEqual([]); });
  it('keeps an editable cover letter on its vacancy', async () => { const app = make(); const created = await app.inject({ method: 'POST', url: '/api/snapshots/import', headers: { authorization: 'Bearer token' }, payload: snapshot }); const id = created.json().job_id; const updated = await app.inject({ method: 'PATCH', url: `/api/jobs/${id}`, payload: { cover_letter_text: 'Dear Hiring Manager,\n\nI am interested in this role.' } }); expect(updated.statusCode).toBe(200); expect(updated.json()).toMatchObject({ cover_letter_text: 'Dear Hiring Manager,\n\nI am interested in this role.', cover_letter_updated_at: expect.any(String) }); expect((await app.inject({ method: 'GET', url: `/api/jobs/${id}` })).json()).toMatchObject({ cover_letter_text: 'Dear Hiring Manager,\n\nI am interested in this role.' }); });
  it('requires the extension bearer token for imports', async () => { const response = await make().inject({ method: 'POST', url: '/api/snapshots/import', payload: snapshot }); expect(response.statusCode).toBe(401); });
  it('reports whether a supplied health-check token can import', async () => { const app = make(); const valid = await app.inject({ method: 'GET', url: '/api/health', headers: { authorization: 'Bearer token' } }); const invalid = await app.inject({ method: 'GET', url: '/api/health', headers: { authorization: 'Bearer wrong' } }); expect(valid.json()).toMatchObject({ ok: true, import_authorized: true }); expect(invalid.statusCode).toBe(401); });
  it('permits CORS preflight only for Chrome extension origins', async () => { const app = make(); const allowed = await app.inject({ method: 'OPTIONS', url: '/api/snapshots/import', headers: { origin: 'chrome-extension://abcdefghijklmnopabcdefghijklmnop' } }); const denied = await app.inject({ method: 'OPTIONS', url: '/api/snapshots/import', headers: { origin: 'https://example.test' } }); expect(allowed.statusCode).toBe(204); expect(allowed.headers['access-control-allow-origin']).toBe('chrome-extension://abcdefghijklmnopabcdefghijklmnop'); expect(allowed.headers['access-control-allow-headers']).toContain('x-client-request-id'); expect(denied.statusCode).toBe(403); });
